INSERT INTO testimonials (id, name, role, content, rating, featured, created_at) VALUES 
('cassio-silva', 'Cassio Silva Takarada', 'Peregrino Dedicado', 'O Caminho do Perdão pra mim é mais que uma superação física. Além de me conectar mais com Deus e seu propósito, desde minha primeira edição venho com a minha família, a qual é minha motivação para continuar persistindo na fé.', 5, 1, datetime('now')),
('teresa-silva', 'Teresa Oliveira Silva', 'Mãe Peregrина', 'Caminhar ao lado dos meus filhos no Caminho do Perdão foi transformador. Não apenas para mim, mas para toda minha família. Voltamos renovados e com uma conexão espiritual mais profunda.', 5, 0, datetime('now')),
('lucas-mendes', 'Lucas Mendes', 'Jovem Peregrino', 'Esperava apenas uma caminhada, mas recebi muito mais. O perdão que aprendi transformou meus relacionamentos e minha forma de ver a vida. Recomendo para todos que buscam paz interior.', 5, 0, datetime('now')),
('patricia-santos', 'Patrícia Santos Costa', 'Coordenadora Voluntária', 'Participei da organização e foi tão gratificante quanto caminhar. Ver pessoas se transformando e encontrando propósito é o maior presente. O Caminho do Perdão mudou minha vida para sempre.', 5, 0, datetime('now')),
('andresa-mendes-takarada', 'Andresa Mendes Takarada de Magalhães', 'Peregrina', 'Conheci o Caminho do Perdão em 2022. Nesse ano meu marido fez o Caminho sozinho. No ano de 2023 foi minha primeira vez como peregrina, confesso que sou sedentária, mas havia um objetivo maior, a gravidez gemelar da minha irmã. Nesse mesmo ano fui acompanhada de vários irmãos da comunidade Tenda 2 Santa Mônica, a qual pertenço. Nos anos de 2024 e 2025 vários primos, primas e tio foram também se tornando peregrinos, além dos meus filhos e meu esposo. O Caminho do Perdão entrou no nosso calendário anual de peregrinações. Foi onde conheci, durante a confissão, o padre Mateus. Um padre sábio, que me ajudou a passar um momento de minha vida onde o luto era de difícil aceitação. Amigos do meu filho se uniram a nós, o que me deixa totalmente realizada, porque os nossos frutos já estão gerando frutos. E divulgando o Caminho do Perdão. Durante o trajeto a paz, o silêncio e a doação se faz presente a cada passo. Sempre voltamos mais fortes na fé e com a certeza que Deus é bom o tempo todo!', 5, 1, datetime('now')),
('gabriel-ferreira', 'Gabriel Ferreira', 'Profissional em Transição', 'Carreguei muito peso das minhas mágoas. Neste Caminho deixei muita coisa para trás e retornei leve, com esperança renovada e propósito claro.', 5, 1, datetime('now'));
